import sys

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    idx = 0
    try:
        n = int(input_data[idx].strip())
        idx += 1
    except ValueError:
        return

    categories = []

    for _ in range(n):
        parts = input_data[idx].split()
        idx += 1
        cat_name = parts[0]
        w = int(parts[1])
        words = parts[2:2+w]
        categories.append((cat_name, set(words)))

    statement_lines = input_data[idx:]
    statement_words = []
    for line in statement_lines:
        statement_words.extend(line.split())

    scores = {}
    for cat_name, keywords in categories:
        count = 0
        for word in statement_words:
            if word in keywords:
                count += 1
        scores[cat_name] = count

    if not scores:
        return

    max_score = max(scores.values())
    result_categories = [name for name, score in scores.items() if score == max_score]
    result_categories.sort()

    for cat in result_categories:
        print(cat)

if __name__ == "__main__":
    main()
